using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Rendering.HighDefinition;using Object=UnityEngine.Object;
public static class ValidateSceneLightVisibility {
 static Scene scene;static Transform root;static List<string> report;static int passed,failed;
 static void Check(bool ok,string message){report.Add((ok?"PASS ":"FAIL ")+message);if(ok)passed++;else failed++;}
 static Light Light(string name,Vector3 pos,LightType type=LightType.Point,LightmapBakeType bake=LightmapBakeType.Realtime,LightShadows shadows=LightShadows.Hard,bool enabled=true){var g=new GameObject(name);g.transform.SetParent(root,false);g.transform.localPosition=pos;var l=g.AddComponent<Light>();l.type=type;l.lightmapBakeType=bake;l.shadows=shadows;l.enabled=enabled;return l;}
 static void Set(Object target,string field,Action<SerializedProperty> update){var so=new SerializedObject(target);update(so.FindProperty(field));so.ApplyModifiedPropertiesWithoutUndo();}
 static Vector3 Angle(float degrees)=>new Vector3(Mathf.Tan(degrees*Mathf.Deg2Rad)*10,0,10);
 public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");report=new List<string>();passed=failed=0;var realLights=Object.FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None);var realEnabled=realLights.Select(l=>l.enabled).ToArray();var realShadows=realLights.Select(l=>l.shadows).ToArray();scene=SceneManager.CreateScene("Light visibility validation fixture");var fixture=new GameObject("Temporary light validation fixture");SceneManager.MoveGameObjectToScene(fixture,scene);root=fixture.transform;
 try{
  var cameraGo=new GameObject("Fixture view camera");cameraGo.transform.SetParent(root,false);var cam=cameraGo.AddComponent<Camera>();cam.fieldOfView=60;cam.aspect=1;cam.cullingMask=0;
  var near=Light("Near HDRP light",new Vector3(0,0,10));var hd=near.gameObject.AddComponent<HDAdditionalLightData>();near.shadows=LightShadows.Hard;
  var far=Light("Far light",new Vector3(0,0,30),shadows:LightShadows.Soft);var behind=Light("Behind light",new Vector3(0,0,-8),shadows:LightShadows.Soft);var area=Light("Area light",new Vector3(1,0,12),LightType.Rectangle);
  var disabled=Light("Authored disabled",new Vector3(0,0,8),enabled:false);var edge=Light("View edge",Angle(39));var directional=Light("Directional excluded",new Vector3(0,0,-20),LightType.Directional);var baked=Light("Baked excluded",new Vector3(0,0,-15),bake:LightmapBakeType.Baked);var mixed=Light("Mixed excluded",new Vector3(0,0,-15),bake:LightmapBakeType.Mixed);var excluded=Light("Explicit exclusion",new Vector3(0,0,-12));
  var managerGo=new GameObject("Fixture controller");managerGo.transform.SetParent(root,false);managerGo.SetActive(false);var manager=managerGo.AddComponent<SceneLightVisibilityController>();manager.ViewCamera=cam;Set(manager,"nearbyKeepAliveDistance",p=>p.floatValue=0);Set(manager,"excludedLights",p=>{p.arraySize=1;p.GetArrayElementAtIndex(0).objectReferenceValue=excluded;});managerGo.SetActive(true);manager.EvaluateNow();
  Check(manager.ManagedLightCount==6,"Only same-scene realtime non-directional lights are registered");Check(near.enabled&&near.shadows==LightShadows.Hard,"Near visible HDRP light and authored hard shadows remain on");Check(hd.GetComponent<Light>().shadows==LightShadows.Hard,"HDRP light component observes managed shadow state");Check(far.enabled&&far.shadows==LightShadows.None,"Far visible light remains lit without shadows");Check(!behind.enabled&&behind.shadows==LightShadows.None,"Light behind camera is culled");Check(area.enabled,"Realtime area lights are managed");Check(!disabled.enabled,"Authored disabled light stays disabled");Check(directional.enabled&&directional.shadows==LightShadows.Hard,"Directional lighting is untouched");Check(baked.enabled&&mixed.enabled&&baked.shadows==LightShadows.Hard&&mixed.shadows==LightShadows.Hard,"Baked and mixed lights are untouched");Check(excluded.enabled&&excluded.shadows==LightShadows.Hard,"Explicitly excluded light is untouched");
  cam.transform.rotation=Quaternion.Euler(0,180,0);manager.EvaluateNow();Check(!near.enabled&&!far.enabled&&behind.enabled&&behind.shadows==LightShadows.Soft,"Turning camera swaps visible lights and preserves soft shadows");cam.transform.rotation=Quaternion.identity;
  near.transform.position=new Vector3(0,0,17.9f);manager.EvaluateNow();near.transform.position=new Vector3(0,0,19);manager.EvaluateNow();Check(near.shadows==LightShadows.Hard,"Shadow exit buffer retains shadows at 19m");near.transform.position=new Vector3(0,0,20.1f);manager.EvaluateNow();Check(near.shadows==LightShadows.None,"Shadows switch off beyond 20m buffered distance");near.transform.position=new Vector3(0,0,19);manager.EvaluateNow();Check(near.shadows==LightShadows.None,"Shadow re-entry waits until 18m");near.transform.position=new Vector3(0,0,17.9f);manager.EvaluateNow();Check(near.shadows==LightShadows.Hard,"Shadows restore inside 18m");near.transform.position=new Vector3(0,0,10);
  edge.transform.position=Angle(42);manager.EvaluateNow();Check(edge.enabled,"View exit buffer retains a previously visible edge light");edge.transform.position=Angle(46);manager.EvaluateNow();Check(!edge.enabled,"Light switches off beyond view exit margin");edge.transform.position=Angle(42);manager.EvaluateNow();Check(!edge.enabled,"View re-entry uses tighter entry margin");edge.transform.position=Angle(39);manager.EvaluateNow();Check(edge.enabled,"Light restores inside view entry margin");
  manager.SetLightEnabled(near,false);Check(!near.enabled,"Gameplay API can switch a managed light off");cam.transform.rotation=Quaternion.Euler(0,180,0);manager.SetLightEnabled(near,true);Check(!near.enabled,"Gameplay enable still respects view culling");cam.transform.rotation=Quaternion.identity;manager.EvaluateNow();Check(near.enabled,"Gameplay-enabled light returns when viewed");near.enabled=false;manager.EvaluateNow();Check(!near.enabled,"Distinct external disable is respected");near.enabled=true;manager.EvaluateNow();Check(near.enabled,"Distinct external re-enable is respected");near.shadows=LightShadows.Soft;manager.EvaluateNow();Check(near.shadows==LightShadows.Soft,"External shadow type change is preserved");near.shadows=LightShadows.Hard;manager.EvaluateNow();
  near.gameObject.SetActive(false);manager.EvaluateNow();Check(near.enabled&&!near.isActiveAndEnabled,"Inactive light hierarchy retains authored component state");near.gameObject.SetActive(true);manager.EvaluateNow();Check(near.enabled,"Reactivated hierarchy is evaluated");
  var spawned=Light("Spawned runtime light",new Vector3(0,0,5));manager.RefreshLights();manager.EvaluateNow();Check(manager.ManagedLightCount==7&&spawned.enabled,"New runtime light discovered by rescan");Object.DestroyImmediate(spawned.gameObject);manager.RefreshLights();manager.EvaluateNow();Check(manager.ManagedLightCount==6,"Destroyed runtime light removed safely");
  cam.transform.rotation=Quaternion.Euler(0,180,0);manager.EvaluateNow();near.type=LightType.Directional;manager.RefreshLights();manager.EvaluateNow();Check(near.enabled&&near.shadows==LightShadows.Hard&&manager.ManagedLightCount==5,"Light changing to directional leaves management with authored state restored");near.type=LightType.Point;manager.RefreshLights();cam.transform.rotation=Quaternion.identity;manager.EvaluateNow();
  cam.enabled=false;manager.EvaluateNow();Check(behind.enabled&&behind.shadows==LightShadows.Soft&&far.shadows==LightShadows.Soft,"Unavailable camera restores original lighting");cam.enabled=true;manager.EvaluateNow();Check(!behind.enabled&&far.shadows==LightShadows.None,"Camera return resumes view/shadow culling");
  manager.enabled=false;Check(near.enabled&&behind.enabled&&!disabled.enabled&&far.shadows==LightShadows.Soft&&near.shadows==LightShadows.Hard,"Disabling controller restores authored on/off and shadow types");manager.enabled=true;manager.EvaluateNow();Check(!behind.enabled&&near.enabled,"Re-enabling controller rescans and resumes correctly");
  var duplicateGo=new GameObject("Duplicate controller");duplicateGo.transform.SetParent(root,false);var duplicate=duplicateGo.AddComponent<SceneLightVisibilityController>();Check(!duplicate.enabled,"Duplicate controller in the same scene cannot compete for lights");Object.DestroyImmediate(duplicateGo);
  Set(manager,"nearbyKeepAliveDistance",p=>p.floatValue=8);Set(manager,"nearbyDistanceHysteresis",p=>p.floatValue=1);behind.transform.position=new Vector3(0,0,-7.9f);manager.EvaluateNow();Check(behind.enabled&&behind.shadows==LightShadows.Soft,"Nearby light behind camera stays on with its authored shadows");
  behind.transform.position=new Vector3(0,0,-8.5f);manager.EvaluateNow();Check(behind.enabled,"Nearby exit buffer retains offscreen light at 8.5m");behind.transform.position=new Vector3(0,0,-9.1f);manager.EvaluateNow();Check(!behind.enabled,"Offscreen light switches off beyond 9m buffered nearby radius");behind.transform.position=new Vector3(0,0,-8.5f);manager.EvaluateNow();Check(!behind.enabled,"Nearby re-entry waits until 8m");behind.transform.position=new Vector3(0,0,-7.9f);manager.EvaluateNow();Check(behind.enabled,"Offscreen light restores inside nearby radius");Check(!disabled.enabled,"Nearby exception does not revive authored-disabled lights");
  manager.SetLightEnabled(behind,false);Check(!behind.enabled,"Gameplay off switch overrides nearby exception");manager.SetLightEnabled(behind,true);Check(behind.enabled,"Gameplay enable restores nearby offscreen illumination");Set(manager,"shadowDistance",p=>p.floatValue=3);Set(manager,"shadowDistanceHysteresis",p=>p.floatValue=0);manager.EvaluateNow();Check(behind.enabled&&behind.shadows==LightShadows.None,"Nearby illumination still obeys independent shadow distance");Set(manager,"shadowDistance",p=>p.floatValue=18);Set(manager,"shadowDistanceHysteresis",p=>p.floatValue=2);manager.EvaluateNow();Check(behind.shadows==LightShadows.Soft,"Authored shadow type restores when shadow distance permits");
  Set(manager,"nearbyKeepAliveDistance",p=>p.floatValue=0);manager.EvaluateNow();Check(!behind.enabled,"Zero nearby radius disables exception even after it was active");Set(manager,"nearbyKeepAliveDistance",p=>p.floatValue=8);cam.transform.position=new Vector3(0,0,40);manager.EvaluateNow();Check(!behind.enabled,"Moving camera away resumes offscreen culling");cam.transform.position=new Vector3(0,0,-5);manager.EvaluateNow();Check(behind.enabled,"Moving camera near enables offscreen light");cam.transform.position=Vector3.zero;manager.EvaluateNow();
  for(int i=0;i<50;i++)manager.EvaluateNow();var watch=System.Diagnostics.Stopwatch.StartNew();long allocatedBefore=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<500;i++)manager.EvaluateNow();long allocated=GC.GetAllocatedBytesForCurrentThread()-allocatedBefore;watch.Stop();Check(allocated==0,"500 stable view updates allocate "+allocated+" managed bytes");report.Add("Stable 6-light fixture evaluation average: "+(watch.Elapsed.TotalMilliseconds/500).ToString("F4")+"ms; no GPU/frame-rate claim.");
  bool untouched=true;for(int i=0;i<realLights.Length;i++)if(realLights[i]&&(realLights[i].enabled!=realEnabled[i]||realLights[i].shadows!=realShadows[i]))untouched=false;Check(untouched,"Other-scene light states were not altered by fixture controller");
 }finally{Object.DestroyImmediate(fixture);SceneManager.UnloadSceneAsync(scene);}
 string result=passed+" passed, "+failed+" failed\n"+string.Join("\n",report);File.WriteAllText("output/Lighting/validation.txt",result);return result;
 }
}
